from stockroom import ParseError, parse_catalog, parse_movements, parse_orders
MAX_PRICE = "1000000.00"
MAX_QUANTITY = 1000000000

from .support import FolderCase

BIG_PRICE = "123456789012345678901234567890"


class LimitTests(FolderCase):
    def assertRefused(self, argv, file, line):
        code, out, err = self.run_cli(*argv)
        self.assertEqual((code, out), (1, ""))
        self.assertTrue(err.startswith("stockroom: %s: line %d: " % (file, line)), err)
        self.assertNotIn("Traceback", err)
        self.assertEqual(err.count("\n"), 1)

    def test_huge_price_refused_for_every_command(self):
        for digits in (BIG_PRICE, "9" * 5000, "1000000.01"):
            with self.subTest(price=digits[:12]):
                self.standard(catalog="# c\nAB-100|g|%s|5\n" % digits)
                for argv in (["stock"], ["low", "--json"], ["quote", "SO-1001"], ["report"]):
                    self.assertRefused(argv, "catalog.txt", 2)

    def test_price_at_the_limit_works(self):
        self.standard(catalog="AB-100|g|%s|5\n" % MAX_PRICE, movements="", orders="SO-1 2024-03-03 x AB-100*1\n")
        self.assertEqual(self.run_cli("stock")[0], 0)
        code, out, _ = self.run_cli("quote", "SO-1")
        self.assertEqual(code, 0)
        self.assertIn("subtotal 1000000.00", out)

    def test_huge_stock_sum_refused_not_traceback(self):
        nines = "9" * 4300
        self.standard(movements="2024-03-01 AB-100 +%s\n2024-03-02 AB-100 +%s\n" % (nines, nines))
        for argv in (["stock"], ["stock", "--json"], ["history", "AB-100"], ["low"]):
            self.assertRefused(argv, "movements.txt", 1)

